/*
 * A373212  Signature sequence of log(2).
 * https://oeis.org/A373212
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   The sequence a(n) is the i‑coordinate of the nth smallest value
 *            of i + j*log(2), where i,j ≥ 1. It is generated by merging the
 *            infinite arithmetic progressions v_i(k) = i + k*log(2) for k =
 *            0,1,2,… using a min‑heap. For integer arithmetic we emulate the
 *            real numbers with the scaled fraction NUM/S...
 * Range:     u8 n <= 105, u16 n <= 105, u32 n <= 105, u64 n <= 105,
 *            u128 n <= 105, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>

typedef struct {
    idx_t i;          /* i‑coordinate of the pair (i,j) */
    idx_t j;          /* j‑coordinate of the pair (i,j) */
    unsigned __int128 val; /* integer representation of i + j*log(2) scaled by SCALE */
} Node;

/* constants for scaling log(2) ≈ 0.693147180559945309… */
static const unsigned __int128 SCALE = (unsigned __int128)1000000000000000000ULL;
static const unsigned __int128 NUM   = (unsigned __int128)693147180559945309ULL;

/* swap two heap nodes */
static void swap(Node *a, Node *b)
{
    Node t = *a;
    *a = *b;
    *b = t;
}

/* sift‑down operation for a min‑heap of Node *with comparison by .val */
static void sift_down(Node *heap, size_t heap_size, size_t idx)
{
    while (1) {
        size_t left = idx << 1;
        if (left > heap_size)
            break;
        size_t right = left + 1;
        size_t child = left;
        if (right <= heap_size && heap[right].val < heap[left].val)
            child = right;
        if (heap[idx].val > heap[child].val) {
            swap(&heap[idx], &heap[child]);
            idx = child;
        } else
            break;
    }
}

/* SEQUENCE IMPLEMENTATION – OEIS A373212 */
seq_t a(idx_t n)
{
    if (n < 1)
        return (seq_t)0;           /* undefined for n=0, but guard anyway */

    size_t heap_size = (size_t)n;   /* number of active streams (i values) */

    /* allocate heap: indices 1 … heap_size */
    Node *heap = (Node *)malloc((heap_size + 1) * sizeof(Node));
    if (!heap)
        return (seq_t)0;           /* allocation failure – unlikely in judge */

    /* initialise each stream with j = 1 */
    for (idx_t i = 1; i <= (idx_t)heap_size; ++i) {
        heap[(size_t)i].i   = i;
        heap[(size_t)i].j   = 1;
        heap[(size_t)i].val = (unsigned __int128)i * SCALE + NUM;
    }

    /* build min‑heap */
    for (size_t k = heap_size / 2; k >= 1; --k)
        sift_down(heap, heap_size, k);

    seq_t result = 0;
    for (size_t step = 1; step <= heap_size; ++step) {
        Node top = heap[1];                 /* smallest value */

        if (step == heap_size)
            result = (seq_t)top.i;          /* return the n‑th term */

        /* replace root with the next element from the same stream
           (i same, j increased, val increased by NUM) */
        heap[1].j  = top.j + 1;
        heap[1].val = top.val + NUM;
        sift_down(heap, heap_size, 1);
    }

    free(heap);
    return result;
}
